library("shiny")

shinyServer(function(input,output){

  serie<-reactive({

        if(input$goButton==0)
          return(NULL)

        inFile<-input$fileSerie
        if (is.null(inFile))
          return(NULL)

        temp<-read.csv(inFile$datapath, header=input$header, sep=input$sep, quote=input$quote,na.strings=input$missing)

        if(ncol(temp)< 4)
          return(NULL)

        names(temp)[c(1,2,3,4)]<-c("yy","mm","dd","parametro")

        length(temp$yy)->numDati

        startYear<-min(temp$yy,na.rm=T)
        endYear<-max(temp$yy,na.rm=T)
        #crea calendario fittizio a partire dal 1961
        calendario<-seq.Date(from=as.Date(sprintf("%s-1-1",startYear),format = '%Y-%m-%d'),to=as.Date(sprintf("%s-12-31",endYear),format = '%Y-%m-%d'),by="days")
        matrix(unlist(strsplit(as.character(calendario),"-")),ncol=3,byrow=T)->dddd.temp
        colnames(dddd.temp)<-c("yy","mm","dd")
        dddd<-as.data.frame(dddd.temp,stringsAsFactors=F)
        names(dddd)<-c("yy","mm","dd")
        #convertiamo da stringhe a numeri
        as.integer(dddd$yy)->dddd$yy
        as.integer(dddd$mm)->dddd$mm
        as.integer(dddd$dd)->dddd$dd

        differenza<- length(calendario)-numDati

        rep(NA,differenza)->serie.NA
        c(serie.NA,temp$parametro)->parametro

        cbind(dddd,parametro)

    })

  indici<-reactive({

    if(input$analisi=="short"){

      if(input$temp){#temp TRUE?
        in.blocco2(serie()[,c(4)],drop=T,nmax=input$tempDays)->index
      }else{#temp TRUE?
        in.blocco2(serie()[,c(4)],drop=F,nmax=input$tempDays)->index
      }#temp TRUE?

    }else{

        longPPrec(serie(),nmax=(input$precMonths*30))->index

    }#fine if su analisi

    index
    })

  output$scaricaTabella<-downloadHandler(
    filename=function(){paste("serie_",Sys.time(),".csv",sep="")},
    content=function(file){write.table(data.frame(serie=serie()),file,col.names=T,row.names=F,quote=F)}
  )

  output$scaricaIndici<-downloadHandler(

      filename=function(){paste("indici_",Sys.time(),".csv",sep="")},
      content=function(file){write.table(data.frame(serie=indici()),file,col.names=T,row.names=F,quote=F)}
  )

  output$scaricaSerie<-downloadHandler(

      filename=function(){paste("serie_",Sys.time(),".csv",sep="")},
      content=function(file){write.table(data.frame(serie=serie()),file,col.names=T,row.names=F,quote=F,sep=";")}
  )

  output$anniConBlocchi<-renderUI({
    if(input$goButton==0)
      return()

    if(is.null(indici()))
      return()

    serie()[indici(),]$yy->anni
    unique(sort(anni))->anni
    selectInput(inputId="anniM",label="Anni con blocchi",as.list(anni))
  })

  output$grafico<-renderPlot({

    if(input$goButton==0)
      return()

    if(is.null(indici()))
      return()

    which(serie()$yy==input$anniM)->index.years
    serie()[index.years,]$parametro->>valori
    length(index.years)->>nnd
    index.years[1]->firstDay
    (indici()[indici() %in% index.years] - firstDay)->index.persistenza
    rep(0,length(index.persistenza))->zeri
    plot(x=1:nnd,y=valori,type="l",lwd=1,xlab="obs",ylab="mm")
    points(x=index.persistenza,y=zeri,pch=21,bg="red")
  })

})#fine shinyServer

